function laterLower(values) {
  return values.map((v, i) => {
    let count = 0;
    for (let j = i + 1; j < values.length; j++) if (values[j] < v) count++;
    return count;
  });
}

function laterLower(values) {
  const offset = 10001, size = 20002;
  const tree = new Array(size + 1).fill(0);
  const add = (i) => { for (; i <= size; i += i & -i) tree[i]++; };
  const prefix = (i) => { let s = 0; for (; i > 0; i -= i & -i) s += tree[i]; return s; };
  const out = new Array(values.length).fill(0);
  for (let k = values.length - 1; k >= 0; k--) {
    out[k] = prefix(values[k] + offset - 1);
    add(values[k] + offset);
  }
  return out;
}
